class SnapshotArray {
    private final java.util.TreeMap<Integer, Integer>[] data;
    private int snapId;

    public SnapshotArray(int length) {
        data = new java.util.TreeMap[length];
        for (int i = 0; i < length; i++) {
            data[i] = new java.util.TreeMap<>();
            data[i].put(0, 0);
        }
    }

    public void set(int index, int val) {
        data[index].put(snapId, val);
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        return data[index].floorEntry(snap_id).getValue();
    }
}

class SnapshotArray {
    private final java.util.List<int[]>[] history;
    private int snapId;

    public SnapshotArray(int length) {
        history = new java.util.ArrayList[length];
        for (int i = 0; i < length; i++) {
            history[i] = new java.util.ArrayList<>();
            history[i].add(new int[]{0, 0});
        }
    }

    public void set(int index, int val) {
        java.util.List<int[]> list = history[index];
        int[] last = list.get(list.size() - 1);
        if (last[0] == snapId) {
            last[1] = val;
        } else {
            list.add(new int[]{snapId, val});
        }
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        java.util.List<int[]> list = history[index];
        int lo = 0;
        int hi = list.size() - 1;
        int answer = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (list.get(mid)[0] <= snap_id) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return list.get(answer)[1];
    }
}

class SnapshotArray {
    private final java.util.Map<Integer, java.util.ArrayList<int[]>> histories = new java.util.HashMap<>();
    private int snapId;

    public SnapshotArray(int length) {
    }

    public void set(int index, int val) {
        java.util.ArrayList<int[]> list = histories.computeIfAbsent(index, key -> new java.util.ArrayList<>());
        if (!list.isEmpty() && list.get(list.size() - 1)[0] == snapId) {
            list.get(list.size() - 1)[1] = val;
        } else {
            list.add(new int[]{snapId, val});
        }
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        java.util.ArrayList<int[]> list = histories.get(index);
        if (list == null) {
            return 0;
        }
        int lo = 0;
        int hi = list.size() - 1;
        int answer = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (list.get(mid)[0] <= snap_id) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer == -1 ? 0 : list.get(answer)[1];
    }
}

class SnapshotArray {
    private final java.util.List<int[]>[] history;
    private final java.util.Map<Integer, Integer> pending = new java.util.HashMap<>();
    private int snapId;

    public SnapshotArray(int length) {
        history = new java.util.ArrayList[length];
        for (int i = 0; i < length; i++) {
            history[i] = new java.util.ArrayList<>();
            history[i].add(new int[]{0, 0});
        }
    }

    public void set(int index, int val) {
        pending.put(index, val);
    }

    public int snap() {
        for (java.util.Map.Entry<Integer, Integer> entry : pending.entrySet()) {
            java.util.List<int[]> list = history[entry.getKey()];
            int val = entry.getValue();
            if (list.get(list.size() - 1)[0] == snapId) {
                list.get(list.size() - 1)[1] = val;
            } else if (list.get(list.size() - 1)[1] != val) {
                list.add(new int[]{snapId, val});
            }
        }
        pending.clear();
        return snapId++;
    }

    public int get(int index, int snap_id) {
        java.util.List<int[]> list = history[index];
        int lo = 0;
        int hi = list.size() - 1;
        int answer = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (list.get(mid)[0] <= snap_id) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return list.get(answer)[1];
    }
}

class SnapshotArray {
    private int[][] snapIds;
    private int[][] values;
    private int[] sizes;
    private int snapId;

    public SnapshotArray(int length) {
        snapIds = new int[length][];
        values = new int[length][];
        sizes = new int[length];
        for (int i = 0; i < length; i++) {
            snapIds[i] = new int[1];
            values[i] = new int[1];
            snapIds[i][0] = 0;
            values[i][0] = 0;
            sizes[i] = 1;
        }
    }

    public void set(int index, int val) {
        int size = sizes[index];
        if (snapIds[index][size - 1] == snapId) {
            values[index][size - 1] = val;
            return;
        }
        ensureCapacity(index);
        snapIds[index][sizes[index]] = snapId;
        values[index][sizes[index]] = val;
        sizes[index]++;
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        int lo = 0;
        int hi = sizes[index] - 1;
        int answer = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (snapIds[index][mid] <= snap_id) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return values[index][answer];
    }

    private void ensureCapacity(int index) {
        if (sizes[index] < snapIds[index].length) {
            return;
        }
        int newLength = snapIds[index].length * 2;
        snapIds[index] = java.util.Arrays.copyOf(snapIds[index], newLength);
        values[index] = java.util.Arrays.copyOf(values[index], newLength);
    }
}
